package hypercast

// The one backend: the Rust core built for wasm32-wasip1 and translated to Go by wasm2go
// (internal/core/core.go, regenerated by `go generate` and diffed in CI). An instance is one
// translated module and a scratch region in the module's linear memory, where a door's text,
// format and day periods are copied in and its out-value and fault span copied out. The core
// keeps no state between calls, so any instance serves any door: a call runs on the primary
// instance when its lock is free, else on a pooled one (acquire has why both). A text too
// long for the base scratch runs on a one-off instance sized for it, so neither the primary
// nor the pool keeps the pages.
//
// wasm2go's generated code bounds-checks every memory access and keeps the call stack in Go,
// so a core bug, a guest stack overflow included, is a Go panic and never a corrupted heap.
// The guest stack is 64 KiB (internal/wasm2go/main.go has the measured margin).
//
// The guest is little-endian whatever the host is. Every word this file writes into the
// scratch or reads out of it goes through encoding/binary's little-endian order, and an
// out-value is reinterpreted in place only on a little-endian host (read in cast.go; on a
// big-endian one decodeLE spells each shape out).

import (
	"encoding/binary"
	"fmt"
	"math"
	"sync"
	"sync/atomic"
	"unsafe"

	"github.com/SkunkWerkx/HyperCast/go/internal/core"
	"github.com/google/uuid"
)

const pageSize = 65536

// modulePages is a fresh module's own memory: the guest's 64 KiB stack and the core's
// data, which the scratch starts after. core_test.go pins it against core.New.
const modulePages = 2

// basePages is the scratch of a primary or pooled instance: one page, enough for any text
// of at most baseText bytes.
const basePages uint32 = 1

// hostMaxPages is the most pages a guest memory can hold here: WebAssembly's 65,536, or
// what the host's int can address on a 32-bit platform (the generated memory_grow applies
// the same cap).
const hostMaxPages = min(65536, math.MaxInt>>16)

// The scratch layout, at offsets from the scratch's start: the out-value (16 bytes, the
// widest door's, 8-aligned), the fault span, the 92-byte RawNumFormat and the 40-byte
// RawDayPeriods (each 4-aligned, as the core reads them in place), then the text.
const (
	outOffset     = 0
	faultOffset   = 16
	formatOffset  = 24
	periodsOffset = formatOffset + 92
	textOffset    = periodsOffset + 40
)

// baseText is the longest text the base scratch holds: 65,376 bytes.
const baseText = int(basePages)*pageSize - textOffset

// MaxText is the longest text a door takes, in bytes: the smaller of the guest's slice
// limit (2^31 − 1, isize::MAX on wasm32, which the core's slice::from_raw_parts must not
// exceed on any host) and the guest's address space less the module's own pages and the
// scratch's header, itself capped by the host's page limit on a 32-bit platform. On a 64-bit
// host it is 2,147,483,647. A longer text panics, as a caller bug, before anything is
// allocated: the translated core cannot address it.
const MaxText = min(1<<31-1, hostMaxPages*pageSize-modulePages*pageSize-textOffset)

// instancesCreated counts instances ever created, a hook for the tests that pin when a
// second instance is and is not made.
var instancesCreated atomic.Int64

type instance struct {
	mu      sync.Mutex
	m       *core.Module
	scratch uint32 // byte offset of the scratch region in the module's memory
	pages   uint32 // pages the scratch holds
}

// newInstance creates a module with pages of scratch beyond its own. It reports false when
// the generated memory_grow refuses the growth (the page limits); a host that cannot
// allocate the pages is a runtime fatal, as the caller's own make would be.
func newInstance(pages uint32) (*instance, bool) {
	in := &instance{m: core.New()}
	old := in.m.Xmemory().Grow(int64(pages), hostMaxPages)
	if old < 0 {
		return nil, false
	}
	in.scratch = uint32(old) * pageSize
	in.pages = pages
	instancesCreated.Add(1)
	return in, true
}

// mustNewInstance is newInstance for the base scratch, which every host can address.
func mustNewInstance() *instance {
	in, ok := newInstance(basePages)
	if !ok {
		panic("hypercast: the core's memory cannot grow by one page on this host")
	}
	return in
}

// mem is the module's memory now. Nothing caches it across a call: a grow replaces the
// slice.
func (in *instance) mem() []byte {
	return *in.m.Xmemory().Slice()
}

// scratchPagesFor is the pages a scratch holding a text of n bytes needs, and whether an
// instance can hold them beside the module's own pages. All arithmetic is in uint64 before
// any narrowing.
func scratchPagesFor(n uint64) (pages uint32, ok bool) {
	bytes := n + textOffset
	need := bytes / pageSize
	if bytes%pageSize != 0 {
		need++
	}
	if need+modulePages > hostMaxPages {
		return 0, false
	}
	return uint32(need), true
}

var (
	primaryOnce sync.Once
	thePrimary  *instance
)

// primary is the instance an uncontended call runs on, created on first use so that
// importing the package costs nothing.
func primary() *instance {
	primaryOnce.Do(func() {
		thePrimary = mustNewInstance()
	})
	return thePrimary
}

// The primary and the pool. The core keeps no state between calls, so the primary owns
// nothing; it is the instance an uncontended call finds without touching sync.Pool, and the
// one a GC never takes. sync.Pool drops what it holds across two GCs, so a pool alone would
// make a quiet single-goroutine caller rebuild a 192 KiB instance after every other
// collection, an allocation on a path that otherwise has none. A call takes the primary when
// its lock is free, else an instance from the pool, whose New creates one. sync.Pool bounds
// nothing: it is per-P with a victim cache, and a goroutine preempted inside a call holds its
// instance meanwhile, so the live count tracks the goroutines concurrently inside a door,
// approximately GOMAXPROCS. Only base-sized instances are ever pooled. Under TinyGo the
// scheduler is cooperative and a call never yields, so the primary is always free and the
// pool goes unused, unless a call panicked on the primary (callPlain's comment).
var pool = newPool()

func newPool() *sync.Pool {
	return &sync.Pool{New: func() any { return mustNewInstance() }}
}

// resetPool empties the pool: a test hook, called with no call in flight.
func resetPool() {
	pool = newPool()
}

// acquire returns an instance with the base scratch: the primary, locked, when it is free,
// else a pooled one.
func acquire() (*instance, lease) {
	p := primary()
	if p.mu.TryLock() {
		return p, leasePrimary
	}
	return pool.Get().(*instance), leasePooled
}

// release gives the instance back: the primary's lock, or the pool. A one-off instance is
// dropped.
func release(in *instance, how lease) {
	switch how {
	case leasePrimary:
		in.mu.Unlock()
	case leasePooled:
		pool.Put(in)
	}
}

// A lease is how a call holds its instance, for giving it back.
type lease uint8

const (
	leasePrimary lease = iota // the primary, locked
	leasePooled               // from the pool
	leaseOneOff               // made for one long text and dropped afterwards
)

// acquireFor returns an instance whose scratch holds a text of n bytes: the primary or a
// pooled one for a text that fits the base scratch, else a one-off instance sized for it. A
// text longer than MaxText panics here, before anything is allocated.
func acquireFor(n uintptr) (*instance, lease) {
	if n <= uintptr(baseText) {
		return acquire()
	}
	if n > MaxText {
		panic(fmt.Sprintf("hypercast: a text of %d bytes exceeds MaxText (%d)", n, MaxText))
	}
	pages, ok := scratchPagesFor(uint64(n))
	if !ok {
		panic(fmt.Sprintf("hypercast: the core cannot address a text of %d bytes on this host", n))
	}
	in, ok := newInstance(pages)
	if !ok {
		panic(fmt.Sprintf("hypercast: the core cannot address a text of %d bytes on this host", n))
	}
	return in, leaseOneOff
}

// load copies the text at ptr into the scratch and returns the scratch's offset.
func (in *instance) load(ptr unsafe.Pointer, n uintptr) int32 {
	if n != 0 {
		copy(in.mem()[in.scratch+textOffset:], unsafe.Slice((*byte)(ptr), n))
	}
	return int32(in.scratch)
}

// loadFormat writes the format into the scratch as the core reads it, field by field at
// the offsets interop.go pins: the three words in the guest's little-endian order, then each
// symbol's bytes and length. Nothing takes the format's address but these reads, which
// keeps it on the caller's stack under TinyGo too.
func (in *instance) loadFormat(format *RawNumFormat) {
	dst := in.mem()[in.scratch+formatOffset : in.scratch+formatOffset+92]
	binary.LittleEndian.PutUint32(dst[0:], format.Size)
	binary.LittleEndian.PutUint32(dst[4:], format.Flags)
	binary.LittleEndian.PutUint32(dst[8:], format.DigitZero)
	put8(dst[12:], &format.DecimalSep)
	put8(dst[21:], &format.GroupSep)
	put8(dst[30:], &format.CurrencyDecimalSep)
	put8(dst[39:], &format.CurrencyGroupSep)
	put8(dst[48:], &format.MinusSign)
	put8(dst[57:], &format.PlusSign)
	put8(dst[66:], &format.Percent)
	put16(dst[75:], &format.Currency)
}

// loadPeriods writes the day periods the same way: the size word, then the two designators.
func (in *instance) loadPeriods(periods *RawDayPeriods) {
	dst := in.mem()[in.scratch+periodsOffset : in.scratch+periodsOffset+40]
	binary.LittleEndian.PutUint32(dst[0:], periods.Size)
	put16(dst[4:], &periods.AM)
	put16(dst[21:], &periods.PM)
}

func put8(dst []byte, s *RawSymbol8) {
	copy(dst[:SymbolMaxBytes], s.Bytes[:])
	dst[SymbolMaxBytes] = s.Len
}

func put16(dst []byte, s *RawSymbol16) {
	copy(dst[:CurrencyMaxBytes], s.Bytes[:])
	dst[CurrencyMaxBytes] = s.Len
}

// result reads the verdict back out of the scratch: the out-value's 16 bytes as the core
// wrote them on success, the fault span on a failure.
func (in *instance) result(code int32) (r result) {
	r.code = code
	mem := in.mem()[in.scratch : in.scratch+textOffset]
	switch {
	case code == 0:
		copy((*[16]byte)(unsafe.Pointer(&r.out))[:], mem[outOffset:])
	case code > 0:
		r.fault = rawFault{
			Offset: binary.LittleEndian.Uint32(mem[faultOffset:]),
			Length: binary.LittleEndian.Uint32(mem[faultOffset+4:]),
		}
	}
	return r
}

// bigEndian is whether the host stores a word's high byte first, where the guest stores its
// low byte first.
var bigEndian = binary.NativeEndian.Uint16([]byte{0, 1}) == 1

// decodeLE spells out the out-value of shape V from the guest's little-endian bytes: what
// read does on a big-endian host, where reinterpreting them in place would swap every word.
// Every shape a door reads is here, and core_test.go holds each against the in-place view
// on a little-endian host.
func decodeLE[V any](b *[16]byte) (v V) {
	le := binary.LittleEndian
	switch p := any(&v).(type) {
	case *uint8:
		*p = b[0]
	case *int8:
		*p = int8(b[0])
	case *uint16:
		*p = le.Uint16(b[:])
	case *int16:
		*p = int16(le.Uint16(b[:]))
	case *uint32:
		*p = le.Uint32(b[:])
	case *int32:
		*p = int32(le.Uint32(b[:]))
	case *uint64:
		*p = le.Uint64(b[:])
	case *int64:
		*p = int64(le.Uint64(b[:]))
	case *float32:
		*p = math.Float32frombits(le.Uint32(b[:]))
	case *float64:
		*p = math.Float64frombits(le.Uint64(b[:]))
	case *rawDecimal:
		*p = rawDecimal{Lo: le.Uint64(b[:]), Hi: le.Uint32(b[8:]), Scale: b[12], Negative: b[13]}
	case *RawTimestamp:
		*p = RawTimestamp{Seconds: int64(le.Uint64(b[:])), Nanos: int32(le.Uint32(b[8:]))}
	case *RawDate:
		*p = RawDate{Year: le.Uint16(b[:]), Month: b[2], Day: b[3]}
	case *RawCivil:
		*p = RawCivil{Year: le.Uint16(b[:]), Month: b[2], Day: b[3], Nanos: le.Uint64(b[8:])}
	case *uuid.UUID: // bytes, in order
		*p = *b
	default:
		panic(fmt.Sprintf("hypercast: no little-endian decoding for %T", v))
	}
	return v
}

// Available reports whether the core can be called. The core is compiled into the binary as
// Go source (internal/core), so there is nothing to load and nothing that can fail: it is
// always true. It stays for code written against the load probe every binding carries.
func Available() bool {
	return true
}

// LoadError returns why the core could not be loaded. A compiled-in core always can, so it
// is always nil. Kept for the reason Available is.
func LoadError() error {
	return nil
}

// NativeVersion reports the core's own version as "major.minor.patch" — read from the core
// itself, a literal compiled into the translated file from the crate's version, not from
// this module — so a deployment can confirm which core went into the binary. It cannot fail.
func NativeVersion() string {
	return FormatVersion(packedVersion())
}

// packedVersion is the core's own version, major<<16 | minor<<8 | patch.
func packedVersion() uint32 {
	in, how := acquire()
	v := uint32(in.m.Xhypercast_version())
	release(in, how)
	return v
}

// ---- The calls cast.go's doors make ----------------------------------------------------
//
// Each acquires an instance for its text, copies the text (and the format or day periods)
// into the scratch, calls the core's export with scratch offsets, reads the verdict back and
// releases the instance; the memory slice is read after the call, never cached across it.
// The doors are the generated Module's methods, held as method expressions with no closure,
// since TinyGo would heap-allocate a closure and the zero-allocation tests run there too.
//
// release is not deferred, on purpose. A call that panics part-way is a core bug (a bounds
// check in the generated code), and it leaves the guest's stack pointer wherever the trap
// found it, so the instance must never serve another call: it is abandoned, still locked if
// it was the primary, and later calls take the pool (core_test.go holds both). A deferred release would hand it back.
// Under TinyGo a defer also moves every pointer the function passes on to the heap, the
// format and the day periods among them, which would cost the doors their zero
// allocations there.

// The symbol types cast.go's doors are written against: a door's export as a method
// expression on the generated Module.
type (
	plainSymbol   = func(m *core.Module, ptr, length, out, fault int32) int32
	numericSymbol = func(m *core.Module, ptr, length, format, out, fault int32) int32
)

var (
	symBool      plainSymbol = (*core.Module).Xcast_bool
	symChar      plainSymbol = (*core.Module).Xcast_char
	symUuid      plainSymbol = (*core.Module).Xcast_uuid
	symTimestamp plainSymbol = (*core.Module).Xcast_timestamp
	symDate      plainSymbol = (*core.Module).Xcast_date
	symTime      plainSymbol = (*core.Module).Xcast_time
	symDuration  plainSymbol = (*core.Module).Xcast_duration

	symI8      numericSymbol = (*core.Module).Xcast_i8
	symI16     numericSymbol = (*core.Module).Xcast_i16
	symI32     numericSymbol = (*core.Module).Xcast_i32
	symI64     numericSymbol = (*core.Module).Xcast_i64
	symU8      numericSymbol = (*core.Module).Xcast_u8
	symU16     numericSymbol = (*core.Module).Xcast_u16
	symU32     numericSymbol = (*core.Module).Xcast_u32
	symU64     numericSymbol = (*core.Module).Xcast_u64
	symF32     numericSymbol = (*core.Module).Xcast_f32
	symF64     numericSymbol = (*core.Module).Xcast_f64
	symDecimal numericSymbol = (*core.Module).Xcast_decimal
)

func callPlain(sym plainSymbol, ptr unsafe.Pointer, length uintptr) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	r := in.result(sym(in.m, s+textOffset, int32(length), s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callNumeric(sym numericSymbol, ptr unsafe.Pointer, length uintptr, format *RawNumFormat) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	in.loadFormat(format)
	r := in.result(sym(in.m, s+textOffset, int32(length), s+formatOffset, s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callUnix(ptr unsafe.Pointer, length uintptr, precision uint32) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	r := in.result(in.m.Xcast_unix(s+textOffset, int32(length), int32(precision), s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callDateOrdered(ptr unsafe.Pointer, length uintptr, order uint32) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	r := in.result(in.m.Xcast_date_ordered(s+textOffset, int32(length), int32(order), s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

// nil periods declares nothing and crosses as a null pointer, the English-only call.
func callDateTime(ptr unsafe.Pointer, length uintptr, order uint32, periods *RawDayPeriods) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	var p int32
	if periods != nil {
		in.loadPeriods(periods)
		p = s + periodsOffset
	}
	r := in.result(in.m.Xcast_datetime(s+textOffset, int32(length), int32(order), p, s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callExcelSerial(ptr unsafe.Pointer, length uintptr, epoch uint32) result {
	in, how := acquireFor(length)
	s := in.load(ptr, length)
	r := in.result(in.m.Xcast_excel_serial(s+textOffset, int32(length), int32(epoch), s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callDecimalFromF64(value float64) result {
	in, how := acquire()
	s := int32(in.scratch)
	r := in.result(in.m.Xcast_decimal_from_f64(value, s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callExcelSerialFromF64(value float64, epoch uint32) result {
	in, how := acquire()
	s := int32(in.scratch)
	r := in.result(in.m.Xcast_excel_serial_from_f64(value, int32(epoch), s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callExcelTime(value float64) result {
	in, how := acquire()
	s := int32(in.scratch)
	r := in.result(in.m.Xcast_excel_time(value, s+outOffset, s+faultOffset))
	release(in, how)
	return r
}

func callExcelDuration(value float64) result {
	in, how := acquire()
	s := int32(in.scratch)
	r := in.result(in.m.Xcast_excel_duration(value, s+outOffset, s+faultOffset))
	release(in, how)
	return r
}
